INSERT INTO public.exam_study_catalog(course_id,content_version,subject_slug,content_sha256,unit_ids,answer_key,required_course_id,delay_hours)
SELECT * FROM incoming_study_catalog ON CONFLICT(course_id,content_version) DO NOTHING;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM incoming_study_catalog i JOIN public.exam_study_catalog c USING(course_id,content_version) WHERE (to_jsonb(i)) IS DISTINCT FROM (to_jsonb(c)-'active')) THEN RAISE EXCEPTION 'Registry content changed without a new version';END IF;
END;$$;
COMMIT;
